CREATE TABLE tenant_privacy_policies(tenant_id uuid PRIMARY KEY REFERENCES tenants(id) ON DELETE CASCADE,retention_days integer NOT NULL DEFAULT 730 CHECK(retention_days BETWEEN 7 AND 3650),message_retention_days integer NOT NULL DEFAULT 365 CHECK(message_retention_days BETWEEN 7 AND 3650),audit_retention_days integer NOT NULL DEFAULT 1095 CHECK(audit_retention_days BETWEEN 7 AND 3650),updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE tenant_deletion_requests(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,requested_by text NOT NULL,reason text,status text NOT NULL DEFAULT 'REQUESTED' CHECK(status IN('REQUESTED','APPROVED','REJECTED','COMPLETED')),requested_at timestamptz NOT NULL DEFAULT now(),completed_at timestamptz);
CREATE TABLE tenant_secure_values(tenant_id uuid NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,key text NOT NULL,ciphertext text NOT NULL,iv text NOT NULL,tag text NOT NULL,updated_at timestamptz NOT NULL DEFAULT now(),PRIMARY KEY(tenant_id,key));
CREATE TABLE privacy_audit(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES tenants(id) ON DELETE CASCADE,event_type text NOT NULL,actor_user_id text,detail jsonb NOT NULL DEFAULT '{}'::jsonb,created_at timestamptz NOT NULL DEFAULT now());CREATE INDEX privacy_audit_tenant_time_idx ON privacy_audit(tenant_id,created_at DESC);
